import PropTypes from 'prop-types';
import { useMemo } from 'react';

// material-ui
import { CssBaseline, StyledEngineProvider } from '@mui/material';
import { createTheme, ThemeProvider } from '@mui/material/styles';

// project import
import useConfig from 'utils/useConfig';
import Palette from './palette';
import Typography from './typography';
import CustomShadows from './shadows';
import componentsOverride from './overrides';
import { alpha } from '@mui/material/styles';


// ==============================|| DEFAULT THEME - MAIN ||============================== //

export default function ThemeCustomization({ children, mode: modeProp }) {
  const { themeDirection, mode, presetColor, fontFamily } = useConfig();

  const finalMode = modeProp || mode;

  const theme = useMemo(() => Palette(finalMode, presetColor), [finalMode, presetColor]);

  const themeTypography = useMemo(() => Typography(fontFamily), [fontFamily]);
  const themeCustomShadows = useMemo(() => CustomShadows(theme), [theme]);

  const themeOptions = useMemo(
    () => ({
      breakpoints: {
        values: {
          xs: 0,
          sm: 768,
          md: 1024,
          lg: 1266,
          xl: 1440
        }
      },
      direction: themeDirection,
      mixins: {
        toolbar: {
          minHeight: 60,
          paddingTop: 8,
          paddingBottom: 8
        }
      },
      palette: theme.palette,
      customShadows: themeCustomShadows,
      typography: themeTypography
    }),
    [themeDirection, theme, themeTypography, themeCustomShadows]
  );


  
  const baseTheme = createTheme(themeOptions);
  const themes = createTheme(baseTheme, {
    components: componentsOverride(baseTheme)
  });




  return (
    <StyledEngineProvider injectFirst>
      <ThemeProvider theme={themes}>
        <CssBaseline />
        {children}
      </ThemeProvider>
    </StyledEngineProvider>
  );
}

ThemeCustomization.propTypes = {
  children: PropTypes.node
};



export function getColors(theme, color = 'primary') {
  const c = theme.palette[color] || theme.palette.primary || {};
  const main = c.main || theme.palette.primary.main;
  return {
    lighter: c.lighter || alpha(main, 0.12),
    light: c.light || alpha(main, 0.24),
    main,
    dark: c.dark || alpha(main, 0.8),
    contrastText: c.contrastText || '#fff'
  };
}

export function getShadow(theme, key) {
  const cs = theme.customShadows || {};
  return cs[key] || cs.primaryButton || 'none';
}